34	export class ExitPlanModeTool extends BaseDeclarativeTool<
35	  ExitPlanModeParams,
36	  ToolResult
37	> {
38	  static readonly Name = EXIT_PLAN_MODE_TOOL_NAME;
39	
40	  constructor(
41	    private config: Config,
42	    messageBus: MessageBus,
43	  ) {
44	    const plansDir = config.storage.getPlansDir();
45	    const definition = getExitPlanModeDefinition(plansDir);
46	    super(
47	      ExitPlanModeTool.Name,
48	      'Exit Plan Mode',
49	      definition.base.description!,
50	      Kind.Plan,
51	      definition.base.parametersJsonSchema,
52	      messageBus,
53	    );
54	  }
55	
56	  protected override validateToolParamValues(
57	    params: ExitPlanModeParams,
58	  ): string | null {
59	    if (!params.plan_path || params.plan_path.trim() === '') {
60	      return 'plan_path is required.';
61	    }
62	
63	    // Since validateToolParamValues is synchronous, we use a basic synchronous check
64	    // for path traversal safety. High-level async validation is deferred to shouldConfirmExecute.
65	    const plansDir = resolveToRealPath(this.config.storage.getPlansDir());
66	    const resolvedPath = path.resolve(
67	      this.config.getTargetDir(),
68	      params.plan_path,
69	    );
70	
71	    const realPath = resolveToRealPath(resolvedPath);
72	
73	    if (!isSubpath(plansDir, realPath)) {
74	      return `Access denied: plan path must be within the designated plans directory.`;
75	    }
76	
77	    return null;
78	  }
79	
80	  protected createInvocation(
81	    params: ExitPlanModeParams,
82	    messageBus: MessageBus,
83	    toolName: string,
84	    toolDisplayName: string,
85	  ): ExitPlanModeInvocation {
86	    return new ExitPlanModeInvocation(
87	      params,
88	      messageBus,
89	      toolName,
90	      toolDisplayName,
91	      this.config,
92	    );
93	  }
94	
95	  override getSchema(modelId?: string) {
96	    const plansDir = this.config.storage.getPlansDir();
97	    return resolveToolDeclaration(getExitPlanModeDefinition(plansDir), modelId);
98	  }
99	}
