101	export class ExitPlanModeInvocation extends BaseToolInvocation<
102	  ExitPlanModeParams,
103	  ToolResult
104	> {
105	  private confirmationOutcome: ToolConfirmationOutcome | null = null;
106	  private approvalPayload: ToolExitPlanModeConfirmationPayload | null = null;
107	  private planValidationError: string | null = null;
108	
109	  constructor(
110	    params: ExitPlanModeParams,
111	    messageBus: MessageBus,
112	    toolName: string,
113	    toolDisplayName: string,
114	    private config: Config,
115	  ) {
116	    super(params, messageBus, toolName, toolDisplayName);
117	  }
118	
119	  override async shouldConfirmExecute(
120	    abortSignal: AbortSignal,
121	  ): Promise<ToolExitPlanModeConfirmationDetails | false> {
122	    const resolvedPlanPath = this.getResolvedPlanPath();
123	
124	    const pathError = await validatePlanPath(
125	      this.params.plan_path,
126	      this.config.storage.getPlansDir(),
127	      this.config.getTargetDir(),
128	    );
129	    if (pathError) {
130	      this.planValidationError = pathError;
131	      return false;
132	    }
133	
134	    const contentError = await validatePlanContent(resolvedPlanPath);
135	    if (contentError) {
136	      this.planValidationError = contentError;
137	      return false;
138	    }
139	
140	    const decision = await this.getMessageBusDecision(abortSignal);
141	    if (decision === 'deny') {
142	      throw new Error(
143	        `Tool execution for "${
144	          this._toolDisplayName || this._toolName
145	        }" denied by policy.`,
146	      );
147	    }
148	
149	    if (decision === 'allow') {
150	      // If policy is allow, auto-approve with default settings and execute.
151	      this.confirmationOutcome = ToolConfirmationOutcome.ProceedOnce;
152	      this.approvalPayload = {
153	        approved: true,
154	        approvalMode: this.getAllowApprovalMode(),
155	      };
156	      return false;
157	    }
158	
159	    // decision is 'ask_user'
160	    return {
161	      type: 'exit_plan_mode',
162	      title: 'Plan Approval',
163	      planPath: resolvedPlanPath,
164	      onConfirm: async (
165	        outcome: ToolConfirmationOutcome,
166	        payload?: ToolConfirmationPayload,
167	      ) => {
168	        this.confirmationOutcome = outcome;
169	        if (payload && 'approved' in payload) {
170	          this.approvalPayload = payload;
171	        }
172	      },
173	    };
174	  }
175	
176	  getDescription(): string {
177	    return `Requesting plan approval for: ${this.params.plan_path}`;
178	  }
179	
180	  /**
181	   * Returns the resolved plan path.
182	   * Note: Validation is done in validateToolParamValues, so this assumes the path is valid.
183	   */
184	  private getResolvedPlanPath(): string {
185	    return path.resolve(this.config.getTargetDir(), this.params.plan_path);
186	  }
187	
188	  async execute(_signal: AbortSignal): Promise<ToolResult> {
189	    const resolvedPlanPath = this.getResolvedPlanPath();
190	
191	    if (this.planValidationError) {
192	      return {
193	        llmContent: this.planValidationError,
194	        returnDisplay: 'Error: Invalid plan',
195	      };
196	    }
197	
198	    if (this.confirmationOutcome === ToolConfirmationOutcome.Cancel) {
199	      return {
200	        llmContent:
201	          'User cancelled the plan approval dialog. The plan was not approved and you are still in Plan Mode.',
202	        returnDisplay: 'Cancelled',
203	      };
204	    }
205	
206	    // When a user policy grants `allow` for exit_plan_mode, the scheduler
207	    // skips the confirmation phase entirely and shouldConfirmExecute is never
208	    // called, leaving approvalPayload null.
209	    const payload = this.approvalPayload ?? {
210	      approved: true,
211	      approvalMode: this.getAllowApprovalMode(),
212	    };
213	    if (payload.approved) {
