215	
216	      if (newMode === ApprovalMode.PLAN) {
217	        throw new Error(`Unexpected approval mode: ${newMode}`);
218	      }
219	
220	      this.config.setApprovalMode(newMode);
221	      this.config.setApprovedPlanPath(resolvedPlanPath);
222	
223	      logPlanExecution(this.config, new PlanExecutionEvent(newMode));
224	
225	      const exitMessage = getPlanModeExitMessage(newMode);
226	
227	      return {
228	        llmContent: `${exitMessage}
229	
230	The approved implementation plan is stored at: ${resolvedPlanPath}
231	Read and follow the plan strictly during implementation.`,
232	        returnDisplay: `Plan approved: ${resolvedPlanPath}`,
233	      };
234	    } else {
235	      const feedback = payload?.feedback?.trim();
236	      if (feedback) {
