7	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
8	import path from 'node:path';
9	import * as fs from 'node:fs';
10	import os from 'node:os';
11	import { validatePlanPath, validatePlanContent } from './planUtils.js';
12	
13	describe('planUtils', () => {
14	  let tempRootDir: string;
15	  let plansDir: string;
16	
17	  beforeEach(() => {
18	    tempRootDir = fs.realpathSync(
19	      fs.mkdtempSync(path.join(os.tmpdir(), 'planUtils-test-')),
20	    );
21	    const plansDirRaw = path.join(tempRootDir, 'plans');
22	    fs.mkdirSync(plansDirRaw, { recursive: true });
23	    plansDir = fs.realpathSync(plansDirRaw);
24	  });
25	
26	  afterEach(() => {
27	    if (fs.existsSync(tempRootDir)) {
28	      fs.rmSync(tempRootDir, { recursive: true, force: true });
29	    }
30	  });
31	
32	  describe('validatePlanPath', () => {
33	    it('should return null for a valid path within plans directory', async () => {
34	      const planPath = path.join('plans', 'test.md');
35	      const fullPath = path.join(tempRootDir, planPath);
36	      fs.writeFileSync(fullPath, '# My Plan');
37	
38	      const result = await validatePlanPath(planPath, plansDir, tempRootDir);
39	      expect(result).toBeNull();
40	    });
41	
42	    it('should return error for path traversal', async () => {
43	      const planPath = path.join('..', 'secret.txt');
44	      const result = await validatePlanPath(planPath, plansDir, tempRootDir);
45	      expect(result).toContain('Access denied');
46	    });
47	
48	    it('should return error for non-existent file', async () => {
49	      const planPath = path.join('plans', 'ghost.md');
50	      const result = await validatePlanPath(planPath, plansDir, tempRootDir);
51	      expect(result).toContain('Plan file does not exist');
52	    });
53	
54	    it('should detect path traversal via symbolic links', async () => {
55	      const maliciousPath = path.join('plans', 'malicious.md');
56	      const fullMaliciousPath = path.join(tempRootDir, maliciousPath);
57	      const outsideFile = path.join(tempRootDir, 'outside.txt');
58	      fs.writeFileSync(outsideFile, 'secret content');
59	
60	      // Create a symbolic link pointing outside the plans directory
61	      fs.symlinkSync(outsideFile, fullMaliciousPath);
62	
63	      const result = await validatePlanPath(
64	        maliciousPath,
65	        plansDir,
66	        tempRootDir,
67	      );
68	      expect(result).toContain('Access denied');
69	    });
70	  });
71	
72	  describe('validatePlanContent', () => {
73	    it('should return null for non-empty content', async () => {
74	      const planPath = path.join(plansDir, 'full.md');
75	      fs.writeFileSync(planPath, 'some content');
76	      const result = await validatePlanContent(planPath);
77	      expect(result).toBeNull();
78	    });
79	
80	    it('should return error for empty content', async () => {
81	      const planPath = path.join(plansDir, 'empty.md');
82	      fs.writeFileSync(planPath, '   ');
83	      const result = await validatePlanContent(planPath);
84	      expect(result).toContain('Plan file is empty');
85	    });
86	
87	    it('should return error for unreadable file', async () => {
88	      const planPath = path.join(plansDir, 'ghost.md');
89	      const result = await validatePlanContent(planPath);
90	      // Since isEmpty treats unreadable files as empty (defensive),
91	      // we expect the "Plan file is empty" message.
92	      expect(result).toContain('Plan file is empty');
93	    });
94	  });
