93	interface GetCorrectedFileContentResult {
94	  originalContent: string;
95	  correctedContent: string;
96	  fileExists: boolean;
97	  error?: { message: string; code?: string };
98	}
99	
100	export async function getCorrectedFileContent(
101	  config: Config,
102	  filePath: string,
103	  proposedContent: string,
104	  abortSignal: AbortSignal,
105	): Promise<GetCorrectedFileContentResult> {
106	  let originalContent = '';
107	  let fileExists = false;
108	  let correctedContent = proposedContent;
109	
110	  try {
111	    originalContent = await config
112	      .getFileSystemService()
113	      .readTextFile(filePath);
114	    fileExists = true; // File exists and was read
115	  } catch (err) {
116	    if (isNodeError(err) && err.code === 'ENOENT') {
117	      fileExists = false;
118	      originalContent = '';
119	    } else {
120	      // File exists but could not be read (permissions, etc.)
121	      fileExists = true; // Mark as existing but problematic
122	      originalContent = ''; // Can't use its content
123	      const error = {
124	        message: getErrorMessage(err),
125	        code: isNodeError(err) ? err.code : undefined,
126	      };
127	      // Return early as we can't proceed with content correction meaningfully
128	      return { originalContent, correctedContent, fileExists, error };
129	    }
130	  }
131	
132	  const aggressiveUnescape = !isGemini3Model(config.getActiveModel());
133	
134	  correctedContent = await ensureCorrectFileContent(
135	    proposedContent,
136	    config.getBaseLlmClient(),
137	    abortSignal,
138	    config.getDisableLLMCorrection(),
139	    aggressiveUnescape,
140	  );
141	
142	  return { originalContent, correctedContent, fileExists };
143	}
